import{_ as d,S as l,n as c,p as u,q as t,J as n,C as s,A as a,a2 as o}from"./framework-c4fdf794.js";const p="/images/panel-email-notifications-dialog.png",h="/images/panel-email-notifications-dialog-off.png",g="/images/panel-email-notifications-dialog-i360.png",m={},f={class:"table-of-contents"},v={class:"warning custom-block"};function y(b,e){const i=l("router-link"),r=l("RouterLink");return c(),u("div",null,[e[37]||(e[37]=t("h1",{id:"panel-notifications-icontact-messages",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#panel-notifications-icontact-messages","aria-hidden":"true"},"#"),n(" Panel notifications (iContact messages)")],-1)),t("nav",f,[t("ul",null,[t("li",null,[s(i,{to:"#overview"},{default:a(()=>[...e[0]||(e[0]=[n("Overview",-1)])]),_:1})]),t("li",null,[s(i,{to:"#how-they-are-produced-and-delivered"},{default:a(()=>[...e[1]||(e[1]=[n("How they are produced and delivered",-1)])]),_:1})]),t("li",null,[s(i,{to:"#message-types"},{default:a(()=>[...e[2]||(e[2]=[n("Message types",-1)])]),_:1})]),t("li",null,[s(i,{to:"#choosing-which-message-types-to-receive"},{default:a(()=>[...e[3]||(e[3]=[n("Choosing which message types to receive",-1)])]),_:1}),t("ul",null,[t("li",null,[s(i,{to:"#on-imunifyav-imunifyav"},{default:a(()=>[...e[4]||(e[4]=[n("On ImunifyAV / ImunifyAV+",-1)])]),_:1})]),t("li",null,[s(i,{to:"#on-imunify360"},{default:a(()=>[...e[5]||(e[5]=[n("On Imunify360",-1)])]),_:1})])])]),t("li",null,[s(i,{to:"#configuration-keys"},{default:a(()=>[...e[6]||(e[6]=[n("Configuration keys",-1)])]),_:1}),t("ul",null,[t("li",null,[s(i,{to:"#in-yaml"},{default:a(()=>[...e[7]||(e[7]=[n("In YAML",-1)])]),_:1})]),t("li",null,[s(i,{to:"#via-cli"},{default:a(()=>[...e[8]||(e[8]=[n("Via CLI",-1)])]),_:1})]),t("li",null,[s(i,{to:"#disabling-user-targeted-delivery"},{default:a(()=>[...e[9]||(e[9]=[n("Disabling user-targeted delivery",-1)])]),_:1})])])]),t("li",null,[s(i,{to:"#who-receives-these-messages"},{default:a(()=>[...e[10]||(e[10]=[n("Who receives these messages",-1)])]),_:1})]),t("li",null,[s(i,{to:"#licensing"},{default:a(()=>[...e[11]||(e[11]=[n("Licensing",-1)])]),_:1})]),t("li",null,[s(i,{to:"#requirements"},{default:a(()=>[...e[12]||(e[12]=[n("Requirements",-1)])]),_:1})]),t("li",null,[s(i,{to:"#plesk-managing-delivery-with-plesk-notifications"},{default:a(()=>[...e[13]||(e[13]=[n("Plesk: managing delivery with Plesk Notifications",-1)])]),_:1}),t("ul",null,[t("li",null,[s(i,{to:"#manual-test-advanced"},{default:a(()=>[...e[14]||(e[14]=[n("Manual test (advanced)",-1)])]),_:1})]),t("li",null,[s(i,{to:"#plesk-cli-optional"},{default:a(()=>[...e[15]||(e[15]=[n("Plesk CLI (optional)",-1)])]),_:1})])])]),t("li",null,[s(i,{to:"#cpanel-whm-delivery-via-icontact"},{default:a(()=>[...e[16]||(e[16]=[n("cPanel/WHM: delivery via iContact",-1)])]),_:1})]),t("li",null,[s(i,{to:"#troubleshooting"},{default:a(()=>[...e[17]||(e[17]=[n("Troubleshooting",-1)])]),_:1})])])]),e[38]||(e[38]=t("h2",{id:"overview",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#overview","aria-hidden":"true"},"#"),n(" Overview")],-1)),t("p",null,[e[19]||(e[19]=n("Besides the ",-1)),s(r,{to:"/features/#notifications"},{default:a(()=>[...e[18]||(e[18]=[n("event notifications",-1)])]),_:1}),e[20]||(e[20]=n(" that the server sends by itself, Imunify delivers ",-1)),e[21]||(e[21]=t("strong",null,"generic panel notifications",-1)),e[22]||(e[22]=n(" (also referred to as ",-1)),e[23]||(e[23]=t("strong",null,"iContact messages",-1)),e[24]||(e[24]=n(") through the hosting panel's own notification mechanism:",-1))]),e[39]||(e[39]=o('<ul><li><strong>cPanel/WHM</strong>: delivered via <strong>cPanel iContact</strong> (WHM → <em>Contact Manager</em>)</li><li><strong>Plesk</strong>: delivered by the <strong>Imunify</strong> Plesk extension via <strong>Plesk Notifications</strong> (<em>Tools &amp; Settings → Notifications</em> / Notification Center)</li></ul><p>The two channels are entirely separate, and the difference matters when you are deciding where to look for a missing message:</p><table><thead><tr><th align="left"></th><th align="left">Event notifications</th><th align="left">Panel notifications</th></tr></thead><tbody><tr><td>Generated by</td><td>the server, from its own events</td><td>the Imunify cloud, from telemetry the server uploads</td></tr><tr><td>Delivered by</td><td>the local MTA, or your script</td><td>the hosting panel</td></tr><tr><td>Configured in</td><td><span class="notranslate"><i>Settings → Notifications</i></span> (per event), <span class="notranslate"><code>notifications-config</code></span></td><td><span class="notranslate"><i>Settings → Notifications → Panel notifications</i></span> (per message type), <span class="notranslate"><code>config update</code></span></td></tr><tr><td>Default state</td><td>off, except the malware hook the agent installs on Plesk</td><td>everything on</td></tr><tr><td>Timing</td><td>immediately for scan events; five minutes or more for the aggregated real-time and Proactive Defense events</td><td>up to a day after the event</td></tr><tr><td>Available on</td><td>any supported panel</td><td><b>cPanel/WHM and Plesk only</b></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Panel notifications are produced only when the control panel is cPanel/WHM or Plesk. On any other panel, and in stand-alone mode, the agent does not request them and the <span class="notranslate"><em>Panel notifications</em></span> row is not shown in the UI.</p></div><h2 id="how-they-are-produced-and-delivered" tabindex="-1"><a class="header-anchor" href="#how-they-are-produced-and-delivered" aria-hidden="true">#</a> How they are produced and delivered</h2><ol><li>The agent uploads server telemetry (scan results, detected applications, configuration) to the Imunify cloud.</li><li>The cloud evaluates that telemetry and prepares a notification with a ready-made subject and HTML body, together with a <strong>period limit</strong> for that message type.</li><li>The agent asks the cloud for pending notifications <strong>no more than once every 24 hours</strong>.</li><li>Before delivering, the agent applies the period limit it received, so the same message type is not repeated more often than the cloud allows.</li><li>The message is handed to cPanel iContact or to the Plesk Notification Center, which decides the actual recipients and channels.</li></ol><p>Two consequences follow from this design and account for most support questions:</p><ul><li><strong>There is no &quot;send me a test notification&quot; action.</strong> The content is generated in the cloud, not on the server, so it cannot be triggered locally.</li><li><strong>A configuration change is not reflected immediately.</strong> It reaches the cloud with the next telemetry upload, the cloud evaluates telemetry from the last few days, and the server asks for messages once a day — so a change can take more than a day to show, in either direction.</li></ul><h2 id="message-types" tabindex="-1"><a class="header-anchor" href="#message-types" aria-hidden="true">#</a> Message types</h2><p>Seven message types have a switch of their own. Six of them are addressed to <span class="notranslate">ImunifyAV</span> and <span class="notranslate">ImunifyAV+</span> servers and are never generated for an Imunify360 server; the only type that applies to every product is <span class="notranslate"><strong>Vulnerable scanner version</strong></span>. Each type has its own cooldown, and all but one pair are generated independently — the two WordPress types are mutually exclusive, see below.</p><table><thead><tr><th align="left">UI label</th><th align="left">Configuration key</th><th align="left">Sent when</th><th align="left">Cooldown</th><th align="left">Scope</th></tr></thead><tbody><tr><td>Malware found</td><td><span class="notranslate"><code>malware_found</code></span></td><td>a user or background scan found malicious files on the server within the last 24 hours</td><td>24 hours</td><td><b>ImunifyAV / ImunifyAV+ only</b>; agent 6.7 or later</td></tr><tr><td>Malware detected on websites</td><td><span class="notranslate"><code>malware_detected</code></span></td><td>the website URL scan found malware on one of the sites hosted on the server</td><td>24 hours</td><td><b>ImunifyAV / ImunifyAV+ only</b></td></tr><tr><td>Malicious redirect detected</td><td><span class="notranslate"><code>malicious_redirect_detected</code></span></td><td>a malicious redirect was detected on a website</td><td>24 hours</td><td><b>ImunifyAV / ImunifyAV+ only</b></td></tr><tr><td>Vulnerable scanner version</td><td><span class="notranslate"><code>aibolit_vulnerable</code></span></td><td>the installed AI-Bolit scanner component is older than 32.7.4 and has a known vulnerability; updating Imunify brings the fixed version</td><td>24 hours</td><td>all products, Imunify360 included</td></tr><tr><td>Insecure WordPress version</td><td><span class="notranslate"><code>insecure_wp_core</code></span></td><td>an installed WordPress core has known vulnerabilities. Takes precedence over <span class="notranslate"><code>outdated_wp_core</code></span> for the same server</td><td>7 days</td><td><b>ImunifyAV / ImunifyAV+ only</b></td></tr><tr><td>Outdated WordPress version</td><td><span class="notranslate"><code>outdated_wp_core</code></span></td><td>an installed WordPress core version is outdated <b>and</b> the server does not already qualify for the insecure-version message</td><td>7 days</td><td><b>ImunifyAV / ImunifyAV+ only</b></td></tr><tr><td>Malware scan is not scheduled</td><td><span class="notranslate"><code>scan_not_scheduled</code></span></td><td><span class="notranslate"><code>MALWARE_SCAN_SCHEDULE.interval</code></span> is set to <span class="notranslate"><code>none</code></span> <b>and</b> no user or background scan has run in the last 30 days</td><td>7 days</td><td><b>ImunifyAV / ImunifyAV+ only</b>; agent 6.7 or later</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The two WordPress types never arrive together</p><p>When a server qualifies for <span class="notranslate"><strong>Insecure WordPress version</strong></span>, the cloud drops <span class="notranslate"><strong>Outdated WordPress version</strong></span> for that server in the same run, even though both switches are on. A vulnerable core is also an old core, and the insecure message already tells the administrator to update, so sending both would be redundant. One insecure installation is enough to suppress the outdated message for the <strong>whole server</strong>, not just for that one site. Switch <span class="notranslate"><code>insecure_wp_core</code></span> off and the outdated message is generated as usual.</p></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>These seven are not the only messages that arrive through this channel. The Imunify cloud also sends, for example, a warning when the agent version is outdated, PCI compliance notices, or a report about compromised accounts. Those have no individual switch and are governed by the master switch alone — turning all seven types off is <strong>not</strong> the same as turning panel notifications off.</p></div>',13)),t("div",v,[e[36]||(e[36]=o('<p class="custom-block-title">Important</p><p>The six <span class="notranslate">ImunifyAV / ImunifyAV+</span> types are <strong>never generated for an Imunify360 server</strong>, whatever their switches say. <span class="notranslate"><strong>Malware found</strong></span> in particular is an upgrade prompt addressed to <span class="notranslate">ImunifyAV</span> and <span class="notranslate">ImunifyAV+</span> administrators — Imunify360 already includes everything the message recommends.</p>',2)),t("p",null,[e[26]||(e[26]=n("If you run Imunify360 and want an email whenever a scan finds malware, that is what ",-1)),s(r,{to:"/features/#notifications"},{default:a(()=>[...e[25]||(e[25]=[n("event notifications",-1)])]),_:1}),e[27]||(e[27]=n(" are for: enable the ",-1)),e[28]||(e[28]=t("span",{class:"notranslate"},"ADMIN",-1)),e[29]||(e[29]=n(" target on ",-1)),e[30]||(e[30]=t("span",{class:"notranslate"},"USER_SCAN_MALWARE_FOUND",-1)),e[31]||(e[31]=n(" (scheduled and user scans), ",-1)),e[32]||(e[32]=t("span",{class:"notranslate"},"CUSTOM_SCAN_MALWARE_FOUND",-1)),e[33]||(e[33]=n(" (on-demand scans) and ",-1)),e[34]||(e[34]=t("span",{class:"notranslate"},"REALTIME_MALWARE_FOUND",-1)),e[35]||(e[35]=n(" (uploads).",-1))])]),e[40]||(e[40]=o('<h2 id="choosing-which-message-types-to-receive" tabindex="-1"><a class="header-anchor" href="#choosing-which-message-types-to-receive" aria-hidden="true">#</a> Choosing which message types to receive</h2><p>Go to <span class="notranslate"><em>Settings → Notifications</em></span> and click <span class="notranslate"><em>Manage panel notifications</em></span> in the <span class="notranslate"><em>Panel notifications</em></span> row. The dialog lists only the message types your product can receive, so it looks different on the two products.</p><h3 id="on-imunifyav-imunifyav" tabindex="-1"><a class="header-anchor" href="#on-imunifyav-imunifyav" aria-hidden="true">#</a> On ImunifyAV / ImunifyAV+</h3><p><img src="'+p+'" alt=""></p><ul><li><span class="notranslate"><strong>Enable panel notifications</strong></span> is the master switch. Turning it off stops all panel notifications at once and greys out the individual types, which keep their own values.</li><li>Each of the seven types below has its own toggle. All of them are <strong>on</strong> by default.</li></ul><p><img src="'+h+'" alt=""></p><h3 id="on-imunify360" tabindex="-1"><a class="header-anchor" href="#on-imunify360" aria-hidden="true">#</a> On Imunify360</h3><p><img src="'+g+`" alt=""></p><p>On Imunify360 the dialog offers the master switch and a single type, <span class="notranslate"><strong>Vulnerable scanner version</strong></span>. The other six messages are addressed to <span class="notranslate">ImunifyAV / ImunifyAV+</span> servers and are never generated for Imunify360, so their switches are not shown. The master switch is still the control that matters here: it governs every message that has no switch of its own — the outdated agent version warning, PCI compliance notices, the compromised accounts report and the like. Turning it off silences all of them; turning <span class="notranslate"><strong>Vulnerable scanner version</strong></span> off silences that one message only.</p><p>The hidden types are not dropped from the configuration: <span class="notranslate"><code>DASHBOARD.notifications</code></span> keeps all seven keys on every product, and the dialog saves the six it does not show unchanged.</p><p>Click <span class="notranslate"><em>Apply</em></span> to save. The dialog writes both <span class="notranslate"><code>ADMIN_CONTACTS.enable_icontact_notifications</code></span> (the master switch) and <span class="notranslate"><code>DASHBOARD.notifications</code></span> (the individual types) in a single configuration update.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>The dialog ships with Imunify UI <strong>8.13.1</strong>; the configuration keys behind it come with imunify-antivirus <strong>8.8.2</strong> (the antivirus component is part of both products). Imunify UI 8.13.1 lists all seven types on both products; the product-specific list described above ships with Imunify UI <strong>8.13.2</strong>. The <span class="notranslate"><em>Panel notifications</em></span> row appears only when both conditions hold: the control panel is cPanel/WHM or Plesk, <strong>and</strong> the agent reports a <span class="notranslate"><code>DASHBOARD.notifications</code></span> section in its configuration. If the row is missing on a cPanel or Plesk server, check both versions; the agent side can be verified with:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config show | grep -A8 DASHBOARD
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div></div><h2 id="configuration-keys" tabindex="-1"><a class="header-anchor" href="#configuration-keys" aria-hidden="true">#</a> Configuration keys</h2><p>Panel notifications are controlled by three keys in <span class="notranslate"><em>/etc/sysconfig/imunify360/imunify360.config</em></span> (or a file in <span class="notranslate"><em>/etc/sysconfig/imunify360/imunify360.config.d/</em></span>):</p><table><thead><tr><th align="left">Key</th><th align="left">Default</th><th align="left">Effect</th></tr></thead><tbody><tr><td><span class="notranslate"><code>ADMIN_CONTACTS.enable_icontact_notifications</code></span></td><td><span class="notranslate"><code>True</code></span></td><td>master switch for delivering generic messages through the panel</td></tr><tr><td><span class="notranslate"><code>DASHBOARD.notifications.&lt;type&gt;</code></span></td><td><span class="notranslate"><code>True</code></span></td><td>whether the cloud generates this message type for this server; a type outside the product&#39;s scope is never generated, whatever the value</td></tr><tr><td><span class="notranslate"><code>CONTROL_PANEL.generic_user_notifications</code></span></td><td><span class="notranslate"><code>True</code></span></td><td>whether user-targeted messages may be delivered to panel end users</td></tr></tbody></table><h3 id="in-yaml" tabindex="-1"><a class="header-anchor" href="#in-yaml" aria-hidden="true">#</a> In YAML</h3><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>ADMIN_CONTACTS:
  enable_icontact_notifications: True
DASHBOARD:
  notifications:
    malware_found: True
    malware_detected: True
    malicious_redirect_detected: True
    aibolit_vulnerable: True
    insecure_wp_core: True
    outdated_wp_core: True
    scan_not_scheduled: True
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><h3 id="via-cli" tabindex="-1"><a class="header-anchor" href="#via-cli" aria-hidden="true">#</a> Via CLI</h3><p>Turn everything off (<strong>Imunify360</strong>):</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config update &#39;{&quot;ADMIN_CONTACTS&quot;: {&quot;enable_icontact_notifications&quot;: false}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><p>Turn off the one type Imunify360 receives and keep the rest of the channel:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config update &#39;{&quot;DASHBOARD&quot;: {&quot;notifications&quot;: {&quot;aibolit_vulnerable&quot;: false}}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><p>The same commands on <strong>ImunifyAV/AV+</strong> use the <span class="notranslate"><code>imunify-antivirus</code></span> binary; there all seven types apply, so any of them can be switched off:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify-antivirus config update &#39;{&quot;DASHBOARD&quot;: {&quot;notifications&quot;: {&quot;outdated_wp_core&quot;: false, &quot;insecure_wp_core&quot;: false}}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Turning a type off in <span class="notranslate"><code>DASHBOARD.notifications</code></span> stops the message at the source: the cloud stops generating it for this server as soon as the change reaches the cloud. Because the change travels with the next telemetry upload and the cloud query looks back two days, a message that was already prepared can still arrive shortly after you disable the type.</p></div><h3 id="disabling-user-targeted-delivery" tabindex="-1"><a class="header-anchor" href="#disabling-user-targeted-delivery" aria-hidden="true">#</a> Disabling user-targeted delivery</h3><p>If these notifications should go only to the server administrator and never to end users, disable <span class="notranslate"><code>CONTROL_PANEL.generic_user_notifications</code></span>.</p><p><strong>Imunify360 (global):</strong></p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config update &#39;{&quot;CONTROL_PANEL&quot;: {&quot;generic_user_notifications&quot;: false}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><p><strong>Imunify360 (for a specific user):</strong></p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config update &#39;{&quot;CONTROL_PANEL&quot;: {&quot;generic_user_notifications&quot;: false}}&#39; --user &lt;username&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><p><strong>ImunifyAV/AV+:</strong></p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify-antivirus config update &#39;{&quot;CONTROL_PANEL&quot;: {&quot;generic_user_notifications&quot;: false}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><h2 id="who-receives-these-messages" tabindex="-1"><a class="header-anchor" href="#who-receives-these-messages" aria-hidden="true">#</a> Who receives these messages</h2><p>A notification is addressed either:</p><ul><li>to the <strong>server administrator</strong> (panel admin) — when no specific user is provided, or</li><li>to a <strong>specific panel user</strong> (customer/reseller) — when a target user login is provided.</li></ul><p>User-targeted delivery is controlled by <span class="notranslate"><code>CONTROL_PANEL.generic_user_notifications</code></span> (default: <span class="notranslate"><code>True</code></span>). The final recipients and channels are then decided by the panel: WHM <em>Contact Manager</em> on cPanel, <em>Tools &amp; Settings → Notifications</em> on Plesk.</p><h2 id="licensing" tabindex="-1"><a class="header-anchor" href="#licensing" aria-hidden="true">#</a> Licensing</h2><p>Panel notifications do <strong>not</strong> require an additional add-on license. They are controlled by a configuration option and are available on supported panels where the delivery channel exists (cPanel/WHM, Plesk).</p><h2 id="requirements" tabindex="-1"><a class="header-anchor" href="#requirements" aria-hidden="true">#</a> Requirements</h2><ul><li><strong>Imunify360 or ImunifyAV/AV+</strong> installed and running, with an activated license (the agent needs its cloud identity to request notifications).</li><li><strong>For Plesk delivery</strong>: Plesk installed, and the Imunify extension installed/enabled in Plesk.</li><li><strong>For cPanel delivery</strong>: cPanel/WHM installed, and WHM Contact Manager configured with at least one destination.</li></ul><h2 id="plesk-managing-delivery-with-plesk-notifications" tabindex="-1"><a class="header-anchor" href="#plesk-managing-delivery-with-plesk-notifications" aria-hidden="true">#</a> Plesk: managing delivery with Plesk Notifications</h2><p>When Imunify runs under Plesk, it relies on the <strong>Imunify Plesk extension</strong> to dispatch these messages via Plesk notifications.</p><ul><li><strong>Where you see it</strong>: in Plesk&#39;s Notification Center, and/or as emails depending on your Plesk notification settings.</li><li><strong>Where you configure delivery</strong>: Plesk → <strong>Tools &amp; Settings → Notifications</strong> (choose recipients and optionally add a custom email address).</li></ul><div class="warning custom-block"><p class="custom-block-title">Note</p><p>On Plesk, the agent also registers a script hook of its own — <span class="notranslate"><em>/opt/imunify360/venv/share/imunify360/scripts/send-notifications</em></span> — on the <span class="notranslate">CUSTOM_SCAN_MALWARE_FOUND</span>, <span class="notranslate">USER_SCAN_MALWARE_FOUND</span> and <span class="notranslate">REALTIME_MALWARE_FOUND</span> events, so that malware notifications reach Plesk administrators and their customers through the Notification Center. This hook is part of the event-notification channel, and it is <strong>not</strong> affected by <span class="notranslate"><code>ADMIN_CONTACTS.enable_icontact_notifications</code></span>: setting that key to <span class="notranslate"><code>false</code></span> stops the generic cloud messages but malware notifications continue to be delivered through Plesk. To stop those as well, disable the corresponding events with <span class="notranslate"><code>notifications-config</code></span>.</p></div><div class="warning custom-block"><p class="custom-block-title">Note</p><p>A Plesk customer who has no contact email address in Plesk will not receive the notification addressed to them, and nothing is reported to the administrator — Plesk records <span class="notranslate"><code>Email address &#39;&#39; is invalid</code></span> in <span class="notranslate"><em>/var/log/plesk/panel.log</em></span> while the hook itself exits successfully. If customers report missing notifications, verify that their Plesk accounts have an email address.</p></div><h3 id="manual-test-advanced" tabindex="-1"><a class="header-anchor" href="#manual-test-advanced" aria-hidden="true">#</a> Manual test (advanced)</h3><p>On a server with the Imunify extension installed, run:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>echo &#39;{&quot;message_type&quot;:&quot;Generic&quot;,&quot;params&quot;:{&quot;subject&quot;:&quot;Test Generic&quot;,&quot;body_html&quot;:&quot;&lt;p&gt;Hello from Imunify&lt;/p&gt;&quot;},&quot;user&quot;:&quot;client_login&quot;}&#39; | sudo /opt/imunify360/venv/share/imunify360/scripts/send-notifications
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><p><strong>Payload fields:</strong></p><ul><li><code>message_type</code>: must be <code>Generic</code></li><li><code>params.subject</code>: notification subject</li><li><code>params.body_html</code>: HTML body (preferred)</li><li><code>params.body</code> / <code>params.text</code>: plain-text fallback (optional)</li><li><code>user</code>: Plesk login to receive the message (optional). If omitted, the Admin user is used.</li></ul><p>This verifies the Plesk delivery path only; it does not exercise the cloud side.</p><h3 id="plesk-cli-optional" tabindex="-1"><a class="header-anchor" href="#plesk-cli-optional" aria-hidden="true">#</a> Plesk CLI (optional)</h3><p>Plesk email notification settings can also be managed via <code>plesk bin notification</code>. See: <a href="https://plesk.com/kb/support/how-to-manage-plesk-email-notifications-via-cli/" target="_blank" rel="noopener noreferrer">How to manage Plesk email notifications via CLI</a>.</p><div class="warning custom-block"><p class="custom-block-title"></p><p>We recommend sending security-related Imunify notifications to the <strong>server administrator</strong> (or a dedicated security mailbox) and not to end customers unless you have a clear operational process in place.</p></div><h2 id="cpanel-whm-delivery-via-icontact" tabindex="-1"><a class="header-anchor" href="#cpanel-whm-delivery-via-icontact" aria-hidden="true">#</a> cPanel/WHM: delivery via iContact</h2><p>On cPanel/WHM, Imunify uses cPanel&#39;s iContact system. To manage recipients and channels, use:</p><ul><li>WHM → <strong>Home → Server Contacts → Contact Manager</strong></li></ul><p>Make sure at least one destination (email/SMS/etc.) is configured there. Imunify only controls whether these messages are generated and handed over; delivery is handled by cPanel.</p><h2 id="troubleshooting" tabindex="-1"><a class="header-anchor" href="#troubleshooting" aria-hidden="true">#</a> Troubleshooting</h2><p><strong>Check what is actually enabled on the server.</strong></p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config show | grep -A8 DASHBOARD
imunify360-agent config show | grep -A3 ADMIN_CONTACTS
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></div><p><strong>See what the agent handed to the panel.</strong> Each message the agent passes to cPanel or Plesk is logged to <span class="notranslate"><em>/var/log/imunify360/console.log</em></span> with its subject and body:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>grep -E &quot;cPanel.notify|Plesk.notify&quot; /var/log/imunify360/console.log | tail
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><p>These lines are written <em>before</em> the panel handler runs, so they show that a message reached the server and was handed over — not that the panel delivered it. On Plesk the extension records the outcome in <span class="notranslate"><em>/usr/local/psa/var/modules/imunify360/imunify360-local.log</em></span> (<span class="notranslate"><code>Notification with subject &quot;…&quot; was sent to …</code></span>) and Plesk reports recipient problems in <span class="notranslate"><em>/var/log/plesk/panel.log</em></span>; on cPanel the message is handed to iContact, which applies the <em>Contact Manager</em> settings.</p><p><strong>Nothing can be triggered from the server.</strong> The messages are generated in the cloud from uploaded telemetry, on the cloud&#39;s schedule. If the condition behind a type is present and the type is on, expect the message within the next daily poll; if it does not come, the usual reasons are the type&#39;s cooldown, the product scope in the table above, or telemetry that has not been uploaded yet. A missing <span class="notranslate"><strong>Outdated WordPress version</strong></span> message has one more possible cause: the server also qualifies for <span class="notranslate"><strong>Insecure WordPress version</strong></span>, which suppresses it.</p>`,66))])}const k=d(m,[["render",y],["__file","index.html.vue"]]);export{k as default};
